SET NOCOUNT ON
GO

USE [master]
GO

CREATE DATABASE [Movies_02]
GO

USE [Movies_02]
GO

CREATE TABLE [dbo].[Actor](
	[ActorID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[FirstName] [nvarchar](255) NULL,
	[FamilyName] [nvarchar](255) NULL,
	[FullName]  AS (isnull(([FirstName]+' ')+[FamilyName],[FirstName])) PERSISTED,
	[DateOfBirth] [datetime] NULL,
	[DateOfDeath] [datetime] NULL,
	[Gender] [nvarchar](255) NULL,
	[WikipediaURL] [nvarchar](max) NULL,
	[ImageURL] [nvarchar](max) NULL
)
GO

CREATE TABLE [dbo].[Certificate](
	[CertificateID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Certificate] [nvarchar](255) NULL,
	[ShortDescription] [nvarchar](255) NULL,
	[LongDescription] [nvarchar](max) NULL,
	[BBFCURL] [nvarchar](255) NULL,
	[CertificateImageURL] [nvarchar](255) NULL,
	[BackColour] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Continent](
	[ContinentID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Continent] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Country](
	[CountryID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Country] [nvarchar](255) NULL,
	[ContinentID] [int] NULL,
	[FlagImageURL] [nvarchar](max) NULL
)
GO

CREATE TABLE [dbo].[Director](
	[DirectorID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[FirstName] [nvarchar](255) NULL,
	[FamilyName] [nvarchar](255) NULL,
	[FullName]  AS (isnull(([FirstName]+' ')+[FamilyName],[FirstName])) PERSISTED,
	[DateOfBirth] [datetime] NULL,
	[DateOfDeath] [datetime] NULL,
	[Gender] [nvarchar](255) NULL,
	[WikipediaURL] [nvarchar](max) NULL,
	[ImageURL] [nvarchar](max) NULL
)
GO

CREATE TABLE [dbo].[Film](
	[FilmID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Title] [nvarchar](255) NULL,
	[OriginalTitle] [nvarchar](255) NULL,
	[ReleaseDate] [datetime] NULL,
	[RunTimeMinutes] [smallint] NULL,
	[DirectorID] [int] NULL,
	[StudioID] [int] NULL,
	[CountryID] [int] NULL,
	[LanguageID] [int] NULL,
	[GenreID] [int] NULL,
	[CertificateID] [int] NULL,
	[SourceID] [int] NULL,
	[BudgetDollars] [float] NULL,
	[BoxOfficeDollars] [float] NULL,
	[OscarNominations] [tinyint] NULL,
	[OscarWins] [tinyint] NULL,
	[Review] [nvarchar](max) NULL,
	[SequelToFilmID] [int] NULL,
	[WikipediaURL] [nvarchar](max) NULL,
	[PosterURL] [nvarchar](max) NULL,
	[WiseOwlScore] [tinyint] NULL,
	[IMDBScore] [float] NULL,
	[RottenTomatoesScore] [float] NULL
)
GO

CREATE TABLE [dbo].[Genre](
	[GenreID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Genre] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Language](
	[LanguageID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Language] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[ParentCompany](
	[ParentCompanyID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[ParentCompany] [nvarchar](255) NULL,
	[DateFounded] [datetime] NULL,
	[HeadOfficeAddress] [nvarchar](255) NULL,
	[HeadOfficePostcode] [nvarchar](255) NULL,
	[Employees] [int] NULL,
	[LastRevenueDollars] [float] NULL,
	[LastNetIncomeDollars] [float] NULL,
	[WebsiteURL] [nvarchar](255) NULL,
	[LogoURL] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Role](
	[RoleID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Role] [nvarchar](255) NULL,
	[FilmID] [int] NULL,
	[ActorID] [int] NULL
)
GO

CREATE TABLE [dbo].[Source](
	[SourceID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Source] [nvarchar](255) NULL
)
GO

CREATE TABLE [dbo].[Studio](
	[StudioID] [int] IDENTITY(1,1) NOT NULL PRIMARY KEY,
	[Studio] [nvarchar](255) NULL,
	[OriginalStudioName] [nvarchar](255) NULL,
	[DateFounded] [datetime] NULL,
	[StillActive] [bit] NOT NULL,
	[DateDefunct] [datetime] NULL,
	[HQAddress] [nvarchar](max) NULL,
	[HQPostcode] [nvarchar](255) NULL,
	[HQCountry] [nvarchar](255) NULL,
	[HQLatitude] [nvarchar](255) NULL,
	[HQLongitude] [nvarchar](255) NULL,
	[Employees] [int] NULL,
	[ParentCompanyID] [int] NULL,
	[WebsiteURL] [nvarchar](255) NULL,
	[LogoURL] [nvarchar](255) NULL
)
GO

