INSERT [dbo].[Certificate] ([CertificateID], [Certificate], [ShortDescription], [LongDescription], [BBFCURL], [CertificateImageURL], [BackColour]) VALUES (1, N'U', N'Suitable for all', N'A U film should be suitable for audiences aged four years and over, although it is impossible to predict what might upset any particular child.', N'https://www.bbfc.co.uk/rating/u', N'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/BBFC_U_2019.svg/50px-BBFC_U_2019.svg.png', N'#0ac700')
GO
INSERT [dbo].[Certificate] ([CertificateID], [Certificate], [ShortDescription], [LongDescription], [BBFCURL], [CertificateImageURL], [BackColour]) VALUES (2, N'PG', N'Parental guidance', N'General viewing, but some scenes may be unsuitable for young children. A PG film should not unsettle a child aged around eight or older. Unaccompanied children of any age may watch, but parents are advised to consider whether the content may upset younger, or more sensitive, children.', N'https://www.bbfc.co.uk/rating/pg', N'https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/BBFC_PG_2019.svg/50px-BBFC_PG_2019.svg.png', N'#fbad00')
GO
INSERT [dbo].[Certificate] ([CertificateID], [Certificate], [ShortDescription], [LongDescription], [BBFCURL], [CertificateImageURL], [BackColour]) VALUES (3, N'12A', N'Suitable for 12 years and over', N'Films classified 12A and video works classified 12 contain material that is not generally suitable for children aged under 12. No one younger than 12 may see a 12A film in a cinema unless accompanied by an adult. Adults planning to take a child under 12 to view a 12A film should consider whether the film is suitable for that child. To help them decide, we recommend that they check the Ratings Info for that film in advance. No one younger than 12 may rent or buy a 12 rated video work.', N'https://www.bbfc.co.uk/rating/12', N'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/BBFC_12A_2019.svg/50px-BBFC_12A_2019.svg.png', N'#ff7d13')
GO
INSERT [dbo].[Certificate] ([CertificateID], [Certificate], [ShortDescription], [LongDescription], [BBFCURL], [CertificateImageURL], [BackColour]) VALUES (4, N'15', N'Suitable only for 15 years and over', N'No one younger than 15 may see a 15 film in a cinema. No one younger than 15 may rent or buy a 15 rated video work.', N'https://www.bbfc.co.uk/rating/15', N'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/BBFC_15_2019.svg/50px-BBFC_15_2019.svg.png', N'#fb4f93')
GO
INSERT [dbo].[Certificate] ([CertificateID], [Certificate], [ShortDescription], [LongDescription], [BBFCURL], [CertificateImageURL], [BackColour]) VALUES (5, N'18', N'Suitable only for adults', N'No one younger than 18 may see an 18 film in a cinema. No one younger than 18 may rent or buy an 18 rated video work. Adults should be free to choose their own entertainment.', N'https://www.bbfc.co.uk/rating/18', N'https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/BBFC_18_2019.svg/50px-BBFC_18_2019.svg.png', N'#dc0a0a')
GO
INSERT [dbo].[Certificate] ([CertificateID], [Certificate], [ShortDescription], [LongDescription], [BBFCURL], [CertificateImageURL], [BackColour]) VALUES (6, N'Unknown', N'Unrated or pre-rating system', N'No rating information is available.', N'https://en.wikipedia.org/wiki/British_Board_of_Film_Classification', N'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/BBFC_Exempt_2019.svg/50px-BBFC_Exempt_2019.svg.png', N'#171714')
